{
  "status": "SUPPORTED",
  "task_summary": "Set up refreshments for two people near the TV seating area and ensure the remote is accessible to both.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds food and drink for a single person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      , 
      "candidate_categories": ["cup_and_plate_set", "snack_set"],
      "required_properties": ["holds_drink", "holds_food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      , 
      "candidate_categories": ["remote_control", "controller"],
      "required_properties": ["portable", "wireless"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Supports the refreshment settings and control.",
        "required_count": 1,
        "binding_policy": "SHARED"
      , 
      "candidate_categories": ["table", "desk", "bench"],
      "required_properties": ["flat", "stable"]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Where the two people sit to watch TV.",
        "required_count": 1,
        "binding_policy": "SHARED"
      , 
      "candidate_categories": ["seating_group", "arrangement"],
      "required_properties": ["near_tv", "supports_people"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_provision",
        "relation": "refreshment_setting is near seating_area",
        "participant_roles": ["refreshment_setting", "seating_area"]
      , 
      "required": true
      },
      {
        "id": "control_accessibility",
        "relation": "entertainment_control is accessible to seating_area",
        "participant_roles": ["entertainment_control", "seating_area"]
      , 
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment_setting",
        "operation": "Place refreshment_setting on surface",
        "participant_roles": ["refreshment_setting", "surface"],
        "operation_count": 2
      },
      {
        "id": "place_entertainment_control",
        "operation": "Place entertainment_control on surface",
        "participant_roles": ["entertainment_control", "surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "cup_and_plate_set_on_table", "visual_description": "Two red cups and two white plates on the wooden side table."}
      ],
      "entertainment_control": [
        {"label": "remote_on_table", "visual_description": "A black remote control on the wooden side table."}
      ],
      "surface": [
        {"label": "wooden_side_table", "visual_description": "Long wooden table holding the cups and remote."},
        {"label": "coffee_table", "visual_description": "Low rectangular table in the center of the room."}
      ],
      "seating_area": [
        {"label": "left_armchair", "visual_description": "Armchair on the left side of the seating group."},
        {"label": "right_armchair", "visual_description": "Armchair on the right side of the seating group."}
      ]
    },
    "inspectable_regions": [],
    "inspection_order": []
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
